class RateLimiter:
    def __init__(self, limit):
        self.limit = limit
        self.requests = {}

    def is_allowed(self, user_id, timestamp):
        if user_id in self.requests:
            if timestamp - self.requests[user_id][0] >= 60:
                self.requests[user_id] = (timestamp, 1)
            else:
                if self.requests[user_id][1] < self.limit:
                    self.requests[user_id] = (self.requests[user_id][0], self.requests[user_id][1] + 1)
                else:
                    return False
        else:
            self.requests[user_id] = (timestamp, 1)
        return True

    def secure_compare(self, provided_signature, calculated_signature):
        if len(provided_signature) != len(calculated_signature):
            return False
        result = 0
        for x, y in zip(provided_signature, calculated_signature):
            result |= ord(x) ^ ord(y)
        return result == 0

