import hmac

class FileSystem:
    def __init__(self, root_path):
        self.root_path = root_path
        self.signature = b'secure_signature'

    def _generate_tree(self, path):
        for root, dirs, files in os.walk(path):
            for d in dirs:
                yield os.path.join(root, d)
            for f in files:
                yield os.path.join(root, f)

    def verify_signature(self, provided_signature):
        if hmac.compare_digest(self.signature, provided_signature):
            return "Signature Verified"
        else:
            return "Signature Mismatch"

    def load_hierarchy(self):
        for item in self._generate_tree(self.root_path):
            print("Loading: %s" % item)

