class FileSystemTree:
    def __init__(self):
        self.root = TreeNode("root", "root_signature")

    def find_node(self, name):
        nodes_to_visit = [self.root]
        while nodes_to_visit:
            current_node = nodes_to_visit.pop(0)
            if current_node.name == name:
                return current_node
            for child in current_node.children:
                nodes_to_visit.append(child)
        return None

    def lazy_load_children(self, parent_name, children_info):
        parent_node = self.find_node(parent_name)
        if parent_node is not None:
            for info in children_info:
                if 'name' in info and 'signature' in info:
                    child_node = TreeNode(info['name'], info['signature'])
