def reconcile_transactions(transactions, known_signatures):
    reconciliation_results = {}
    for transaction in transactions:
        transaction_id = transaction['id']
        if transaction_id in known_signatures:
            if transaction['signature'] == known_signatures[transaction_id]:
                reconciliation_results[transaction_id] = "Transaction %s reconciled successfully." % transaction_id
            else:
                reconciliation_results[transaction_id] = "Transaction %s failed signature verification." % transaction_id
        else:
            reconciliation_results[transaction_id] = "Transaction %s is unknown." % transaction_id
    return reconciliation_results

